// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // 1. Deployer is msg.sender; owner is initially address(this) (the test contract)
        // 2. Call allowance to trigger the difference noted: after allowance returns,
        //    the reference keeps _owner = address(this), the mutant would have set it to zero
        //    Actually the mutant changes changeOwner only, but we just need to observe owner()
        //    after deployment (no changeOwner call). In the reference, owner() returns address(this).
        //    In the mutant, owner() returns address(this) as well because changeOwner is never called.
        // Wait — the difference statement says the difference appears after allowance(...) completes.
        // The only way allowance can affect _owner is if there is a bug in allowance that calls changeOwner?
        // Re-reading: "after a call to allowance(...) completes, the value of state variable _owner differs"
        // That implies allowance() somehow changes _owner. So the mutant's allowance must be different.
        // But the mutant description only changes changeOwner. However the instruction says "driven through the public/external entry allowance(address,address), P and M differ".
        // This must be interpreted as: the mutant was changed elsewhere (maybe allowance incorrectly triggers _owner change) but the given diff is the only change? Actually the problem says "Change the assignment so that _owner is set to address(0) instead of newOwner".
        // So the mutant has changeOwner set to address(0). But allowance does not call changeOwner. So after allowance, owner() would be same in both unless something else changed. 
        // The only plausible interpretation: the mutant's allowance also has a bug? No — we must work with given diff.
        // Maybe the test must call changeOwner first? Then allowance? But the question says "driven through the public/external entry allowance". 
        // Let's assume the scenario: deploy, then call changeOwner(someone) which in reference sets _owner = someone, in mutant sets _owner = 0. Then call allowance. 
        // The concrete witness: after changeOwner(alice) and then allowance(alice, bob), reference owner() == alice, mutant owner() == 0.
        // But the instruction says "CHOOSE specific concrete input values and a specific call sequence that, given the difference above, drive the contract to a state where the reference and the bug OBSERVABLY diverge." 
        // So we can call changeOwner then allowance.
        address alice = address(0x123);
        address bob = address(0x456);
        vm.prank(address(this));
        c.changeOwner(alice);
        // Now in reference, owner() == alice; in mutant, owner() == address(0).
        c.allowance(alice, bob); // trigger the divergence
        // Assert: in reference c.owner() == alice, in bug it is address(0) — so we assert the reference property
        assertTrue(c.owner() == alice, "owner should be alice");
    }
}

