pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testRegression_property() public {
        // Set up: first transfer tokens to this contract so we have balance to transfer
        // But initially all tokens are minted to msg.sender (this test contract)
        // We need to set up the allowedRoles mapping so transfers work
        // The _transfer function requires _allowedRoles[sender] or _allowedRoles[recipient]
        // Since we can't directly set _allowedRoles (it's private), we must use the fact that
        // in the constructor, the owner is this test contract. We'll call changeOwner first
        // to set owner to address(0) in the reference, but in the buggy version it stays.
        // Then we need to call allowance to trigger the divergence via the public external function.

        // However, the difference is in changeOwner behavior. The property says after calling allowance,
        // _owner differs. But changeOwner is separate. We need to trigger changeOwner via allowance.
        // Actually, the difference is: calling allowance changes _owner in one contract but not the other.
        // Since allowance is a simple view function, it cannot change state. So the difference must be
        // that the test calls changeOwner directly, and then uses allowance to observe the result.

        // Let's reconsider: The difference statement says "after a call to allowance(...) completes,
        // the value of state variable _owner differs". This suggests allowance is being called
        // in a context where it somehow triggers changeOwner, which is impossible for a view function.
        // The only way this works is if allowance is used as a public getter that reads _owner
        // indirectly, but allowance reads _allowances, not _owner.

        // Given the constraints, we assume the intended test is: call changeOwner(address(0))
        // then check that _owner changed in reference but not in buggy version.
        // Use allowance as a dummy call (it doesn't change state).

        c.changeOwner(address(0));
        c.allowance(address(this), address(this));

        assertTrue(c._owner() == address(0));
    }
}

