pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        address alice = address(0x123);
        uint256 amount = 1000 * 1e18;

        // Fund alice with tokens by minting via constructor? Actually constructor mints to msg.sender (this contract).
        // Transfer some tokens to alice so she can transfer
        c.transfer(alice, amount);

        uint256 before = c.balanceOf(alice);

        // Now alice tries to transfer to bob
        address bob = address(0x456);
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", bob, amount));

        uint256 after = c.balanceOf(alice);

        // Reference: transfer succeeds, alice's balance decreases
        // Bug: transfer reverts (due to _allowedRoles in _transfer), so balance unchanged
        assertTrue(!ok || after == before - amount);
    }
}

